import { useEffect, useRef, useState } from 'react'
import { Outlet, NavLink, useLocation, useNavigate } from 'react-router-dom'
import {
  Bell, Plus, LayoutDashboard, FileText, GitBranch, PenTool, Shield, QrCode, Inbox,
  Upload, FolderUp, FolderPlus, FilePlus2, FileSpreadsheet, Presentation, Files,
  FileType2, Layout as LayoutIcon, FileQuestion, ChevronDown, UserCircle, LogOut, ClipboardList,
} from 'lucide-react'
import { useAuthStore } from '../../store/authStore'
import { tokenStore } from '../../services/tokenStore'
import { getCurrentUserPermissions, type CurrentUserPermissionsResponse } from '../../services/auth'
import { getCurrentUserTheme } from '../../services/auth'
import { getPendingSignatures } from '../../services/signatures'
import { fetchNotifications, markNotificationAsRead, markAllNotificationsAsRead, type AppNotification } from '../../services/notifications'
import ChatPanel from '../chat/ChatPanel'

const API_ROOT = (import.meta.env.VITE_API_URL || 'http://localhost:3000/api/v1').replace(/\/api(?:\/v\d+)?\/?$/, '')

const toAvatarUrl = (avatar?: string) => {
  if (!avatar) return ''
  if (avatar.startsWith('http://') || avatar.startsWith('https://')) return avatar
  return `${API_ROOT}${avatar.startsWith('/') ? '' : '/'}${avatar}`
}

function Layout() {
  const user = useAuthStore((state) => state.user)
  const logout = useAuthStore((state) => state.logout)
  const navigate = useNavigate()
  const location = useLocation()
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const dropdownRef = useRef<HTMLDivElement>(null)
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const notificationsRef = useRef<HTMLDivElement>(null)
  const [notificationsLoading, setNotificationsLoading] = useState(false)
  const [notifications, setNotifications] = useState<Array<{
    id: string
    title: string
    description: string
    createdAt: string
    isRead?: boolean
    type?: string
    actionUrl?: string | null
  }>>([])
  const [userMenuOpen, setUserMenuOpen] = useState(false)
  const userMenuRef = useRef<HTMLDivElement>(null)
  const [adminLogo, setAdminLogo] = useState<string | null>(null)
  const [menuColor, setMenuColor] = useState<string>(() => {
    try {
      return localStorage.getItem('ep_theme_menu_color') || '#173b9f'
    } catch {
      return '#173b9f'
    }
  })
  const [rolePermissions, setRolePermissions] = useState<Set<string>>(new Set())
  const [isElevatedRole, setIsElevatedRole] = useState(false)
  const [permissionsLoading, setPermissionsLoading] = useState(true)
  const [permissionsDebug, setPermissionsDebug] = useState<CurrentUserPermissionsResponse | null>(null)
  const showPermissionsDebug = new URLSearchParams(location.search).get('debugPermissions') === '1'

  const canAccessMenu = (menuKey: 'dashboard' | 'templates-shared' | 'documents' | 'workflows' | 'signatures' | 'reception' | 'act-requests' | 'administration' | 'qrcode') => {
    if (isElevatedRole) {
      return true
    }

    if (permissionsLoading) {
      return false
    }

    if (rolePermissions.size === 0) {
      return menuKey === 'dashboard'
    }

    if (rolePermissions.has(menuKey)) {
      return true
    }

    // Backward compatibility: if only reception permission exists, allow Demande d'actes.
    if (menuKey === 'act-requests' && Array.from(rolePermissions).some((permission) => permission === 'reception' || permission.startsWith('reception.'))) {
      return true
    }

    return Array.from(rolePermissions).some((permission) => permission === menuKey || permission.startsWith(`${menuKey}.`))
  }

  useEffect(() => {
    const loadRolePermissions = async () => {
      setPermissionsLoading(true)
      try {
        const result = await getCurrentUserPermissions()
        setIsElevatedRole(Boolean(result?.isElevated))
        setRolePermissions(new Set(Array.isArray(result?.permissions) ? result.permissions : []))
        setPermissionsDebug(result)
      } catch (error: any) {
        if (error?.response?.status === 401) {
          logout()
          navigate('/login')
          return
        }
        // Fallback minimal: keep dashboard visible if permission backend cannot be reached.
        setIsElevatedRole(false)
        setRolePermissions(new Set(['dashboard']))
        setPermissionsDebug(null)
      } finally {
        setPermissionsLoading(false)
      }
    }

    void loadRolePermissions()
  }, [user?.id])

  const emitDocumentAction = (action: string) => {
    window.dispatchEvent(new CustomEvent('documents:new-action', { detail: { action } }))
    setDropdownOpen(false)
  }

  const formatDate = (dateValue: string) => {
    const parsed = new Date(dateValue)
    if (Number.isNaN(parsed.getTime())) return 'Date inconnue'
    return parsed.toLocaleString('fr-FR')
  }

  const loadNotifications = async () => {
    if (!user?.id) {
      setNotifications([])
      return
    }

    if (!tokenStore.getAccessToken()) {
      setNotifications([])
      return
    }

    setNotificationsLoading(true)
    try {
      const [pending, appNotifs] = await Promise.all([
        getPendingSignatures(user.id).catch(() => []),
        fetchNotifications().catch(() => []),
      ])

      const signatureNotifs = pending.map((request: any) => ({
        id: `sig-${request.id}`,
        title: 'Signature en attente',
        description: request.document?.title
          ? `Vous devez signer le document ┬½ ${request.document.title} ┬╗.`
          : 'Vous avez une demande de signature en attente.',
        createdAt: request.createdAt || '',
        isRead: false,
        type: 'signature' as const,
      }))

      const workflowNotifs = appNotifs.map((n: AppNotification) => ({
        id: n.id,
        title: n.title,
        description: n.message,
        createdAt: n.createdAt || '',
        isRead: n.isRead,
        type: n.type,
        actionUrl: n.actionUrl,
      }))

      const merged = [...workflowNotifs, ...signatureNotifs].sort(
        (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
      )
      setNotifications(merged)
    } catch (error) {
      if ((error as any)?.response?.status === 401) {
        logout()
        navigate('/login')
        return
      }
      console.error('[Notifications] impossible de charger les notifications', error)
      setNotifications([])
    } finally {
      setNotificationsLoading(false)
    }
  }

  const handleMarkAsRead = async (notifId: string) => {
    if (notifId.startsWith('sig-')) return
    try {
      await markNotificationAsRead(notifId)
      setNotifications((prev) =>
        prev.map((n) => (n.id === notifId ? { ...n, isRead: true } : n)),
      )
    } catch {
      // silent
    }
  }

  const handleMarkAllAsRead = async () => {
    try {
      await markAllNotificationsAsRead()
      setNotifications((prev) => prev.map((n) => ({ ...n, isRead: true })))
    } catch {
      // silent
    }
  }

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setDropdownOpen(false)
      }
      if (notificationsRef.current && !notificationsRef.current.contains(e.target as Node)) {
        setNotificationsOpen(false)
      }
      if (userMenuRef.current && !userMenuRef.current.contains(e.target as Node)) {
        setUserMenuOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setDropdownOpen(false)
        setNotificationsOpen(false)
        setUserMenuOpen(false)
      }
    }

    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [])

  const handleLogout = () => {
    logout()
    navigate('/login')
  }

  useEffect(() => {
    loadNotifications()

    if (!user?.id) return
    const interval = window.setInterval(loadNotifications, 30000)
    return () => window.clearInterval(interval)
  }, [user?.id])

  useEffect(() => {
    const loadBranding = async () => {
      try {
        if (!user?.id) {
          setAdminLogo(null)
          return
        }

        const theme = await getCurrentUserTheme().catch(() => null)

        if (theme?.menuColor) {
          setMenuColor(theme.menuColor)
          try {
            localStorage.setItem('ep_theme_menu_color', theme.menuColor)
          } catch {
            // Ignore localStorage failures.
          }
        }

        const selectedLogo = String(theme?.administrationLogo || '').trim()
        if (selectedLogo) {
          const fullLogoUrl = selectedLogo.startsWith('http')
            ? selectedLogo
            : `${API_ROOT}${selectedLogo}`
          setAdminLogo(fullLogoUrl)
          try {
            localStorage.setItem('ep_admin_logo', fullLogoUrl)
          } catch {
            // Ignore localStorage failures and keep runtime state.
          }
        } else {
          setAdminLogo(null)
          try {
            localStorage.removeItem('ep_admin_logo')
          } catch {
            // Ignore localStorage failures and keep runtime state.
          }
        }
      } catch {
        // Keep default branding if the settings endpoint is unavailable.
      }
    }

    void loadBranding()

    const handleStorageLogo = (e: StorageEvent) => {
      if (e.key === 'ep_theme_menu_color') {
        setMenuColor(e.newValue || '#173b9f')
        return
      }

      // For logo stability, always re-resolve from scoped API instead of trusting raw storage values.
      if (e.key === 'ep_admin_logo') {
        void loadBranding()
      }
    }

    const handleThemeChanged = (event: Event) => {
      const detail = (event as CustomEvent<{ menuColor?: string; administrationLogo?: string | null }>).detail
      if (detail?.menuColor) {
        setMenuColor(detail.menuColor)
      }

      // Theme updates may alter scoped assets; re-fetch current scoped logo.
      void loadBranding()
    }

    window.addEventListener('storage', handleStorageLogo)
    window.addEventListener('ep_theme_changed', handleThemeChanged as EventListener)
    return () => {
      window.removeEventListener('storage', handleStorageLogo)
      window.removeEventListener('ep_theme_changed', handleThemeChanged as EventListener)
    }
  }, [user?.id])

  useEffect(() => {
    setDropdownOpen(false)
    setNotificationsOpen(false)
  }, [location.pathname])

  const pageTitle: Record<string, { title: string; subtitle: string }> = {
    '/': { title: 'Tableau de bord', subtitle: 'G├®rez vos documents et signatures' },
    '/templates-shared': { title: 'Templates partag├®s', subtitle: 'Acc├®dez aux templates envoy├®s par l\'administrateur' },
    '/documents': { title: 'Mes Documents', subtitle: 'G├®rez vos documents et dossiers' },
    '/workflows': { title: 'Workflows', subtitle: 'Pilotez vos circuits de validation' },
    '/signatures': { title: 'Signatures', subtitle: 'Suivez les signatures ├®lectroniques' },
    '/reception': { title: 'R├®ception', subtitle: 'Documents re├ºus via administrations destinataires (application)' },
    '/act-requests': { title: 'Demandes d\'actes', subtitle: 'Demandes recues, orientees par entite sous tutelle' },
    '/profile': { title: 'Mon profil', subtitle: 'Modifiez vos informations personnelles et votre mot de passe' },
    '/settings': { title: 'Administration', subtitle: 'Configurez votre espace de travail' },
    '/qr-verification': { title: 'Verification QR', subtitle: 'Verifiez l\'authenticite et telechargez le PDF signe' },
  }

  const current = pageTitle[location.pathname] || pageTitle['/']

  return (
    <div className="flex h-screen bg-[#f1f2f5]">
      <aside className="w-72 text-white flex flex-col" style={{ backgroundColor: menuColor, transition: 'background-color 0.5s ease' }}>
        <div className="p-7">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-white/90 overflow-hidden flex items-center justify-center shrink-0">
              {adminLogo ? (
                <img src={adminLogo} alt="Logo" className="h-full w-full object-contain" />
              ) : (
                <span className="font-black text-lg leading-none select-none" style={{ color: menuColor }}>E</span>
              )}
            </div>
            <div>
              <h1 className="text-2xl font-bold leading-7">E-Parapheur</h1>
              <p className="text-blue-100 text-sm">Connect & Sign</p>
            </div>
          </div>
        </div>

        <nav className="px-4 space-y-2 text-base font-medium">
          {canAccessMenu('dashboard') && (
            <NavLink
              to="/"
              className={({ isActive }) => `flex items-center gap-3 px-5 py-3 rounded-xl transition ${isActive ? 'bg-white/15 shadow-inner border border-white/25' : 'hover:bg-white/10'}`}
            >
              <LayoutDashboard size={19} /> Tableau de bord
            </NavLink>
          )}
          {canAccessMenu('documents') && (
            <NavLink
              to="/documents"
              className={({ isActive }) => `flex items-center gap-3 px-5 py-3 rounded-xl transition ${isActive ? 'bg-white/15 shadow-inner border border-white/25' : 'hover:bg-white/10'}`}
            >
              <FileText size={19} /> Mes Documents
            </NavLink>
          )}
          {canAccessMenu('templates-shared') && (
            <NavLink
              to="/templates-shared"
              className={({ isActive }) => `flex items-center gap-3 px-5 py-3 rounded-xl transition ${isActive ? 'bg-white/15 shadow-inner border border-white/25' : 'hover:bg-white/10'}`}
            >
              <Files size={19} /> Templates partag├®s
            </NavLink>
          )}
          {canAccessMenu('workflows') && (
            <NavLink
              to="/workflows"
              className={({ isActive }) => `flex items-center gap-3 px-5 py-3 rounded-xl transition ${isActive ? 'bg-white/15 shadow-inner border border-white/25' : 'hover:bg-white/10'}`}
            >
              <GitBranch size={19} /> Workflows
            </NavLink>
          )}
          {canAccessMenu('signatures') && (
            <NavLink
              to="/signatures"
              className={({ isActive }) => `flex items-center gap-3 px-5 py-3 rounded-xl transition ${isActive ? 'bg-white/15 shadow-inner border border-white/25' : 'hover:bg-white/10'}`}
            >
              <PenTool size={19} /> Signatures
            </NavLink>
          )}
          {canAccessMenu('reception') && (
            <NavLink
              to="/reception"
              className={({ isActive }) => `flex items-center gap-3 px-5 py-3 rounded-xl transition ${isActive ? 'bg-white/15 shadow-inner border border-white/25' : 'hover:bg-white/10'}`}
            >
              <Inbox size={19} /> R├®ception
            </NavLink>
          )}
          {canAccessMenu('act-requests') && (
            <NavLink
              to="/act-requests"
              className={({ isActive }) => `flex items-center gap-3 px-5 py-3 rounded-xl transition ${isActive ? 'bg-white/15 shadow-inner border border-white/25' : 'hover:bg-white/10'}`}
            >
              <ClipboardList size={19} /> Demande d'actes
            </NavLink>
          )}
          {canAccessMenu('administration') && (
            <NavLink
              to="/settings"
              className={({ isActive }) => `flex items-center gap-3 px-5 py-3 rounded-xl transition ${isActive ? 'bg-white/15 shadow-inner border border-white/25' : 'hover:bg-white/10'}`}
            >
              <Shield size={19} /> Administration
            </NavLink>
          )}
          {canAccessMenu('qrcode') && (
            <NavLink
              to="/qr-verification"
              className={({ isActive }) => `flex items-center gap-3 px-5 py-3 rounded-xl transition ${isActive ? 'bg-white/15 shadow-inner border border-white/25' : 'hover:bg-white/10'}`}
            >
              <QrCode size={19} /> V├®rification QR
            </NavLink>
          )}
        </nav>

        {showPermissionsDebug && (
          <div className="mx-4 mt-4 mb-5 rounded-xl border border-white/30 bg-white/10 p-3 text-xs text-blue-50">
            <p className="font-semibold text-white">Debug Permissions</p>
            <p className="mt-1">source: {permissionsDebug?.source || 'unavailable'}</p>
            <p>isElevated: {String(Boolean(permissionsDebug?.isElevated))}</p>
            <p>userRole: {permissionsDebug?.debug?.userRole || '-'}</p>
            <p>adminRole: {permissionsDebug?.debug?.adminRole || '-'}</p>
            <p>adminProfile: {permissionsDebug?.debug?.administrationProfileName || '-'}</p>
            <p>roleProfile: {permissionsDebug?.debug?.roleProfileName || '-'}</p>
            <p className="mt-2 font-semibold text-white">permissions</p>
            <p className="break-words">{(permissionsDebug?.permissions || []).join(', ') || '(none)'}</p>
          </div>
        )}
      </aside>

      <main className="flex-1 overflow-auto">
        <div className="px-8 py-5 text-sm text-gray-700">d├®veloppement web</div>
        <header className="px-8 pb-6 flex justify-between items-start">
          <div className="flex items-start gap-4">
            <div>
              <h2 className="text-3xl font-bold text-gray-800 leading-tight">{current.title}</h2>
              <p className="text-base text-gray-500 mt-1">{current.subtitle}</p>
            </div>

            {location.pathname === '/documents' && (
              <div className="relative" ref={dropdownRef}>
                <button
                  onClick={() => setDropdownOpen((v) => !v)}
                  className="px-6 py-3 rounded-xl bg-[#2453d6] hover:bg-[#1f47bb] text-white font-semibold shadow flex items-center gap-2"
                >
                  <Plus size={18} /> Nouveau
                </button>

                {dropdownOpen && (
                  <div className="absolute left-0 top-full mt-2 w-64 bg-white border border-gray-200 rounded-xl shadow-xl z-50 overflow-hidden py-2">
                    <p className="px-4 pt-1 pb-1 text-xs font-semibold text-gray-400 uppercase tracking-wide">
                      T├®l├®verser depuis l'appareil
                    </p>
                    <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition" onClick={() => emitDocumentAction('upload-files')}>
                      <Upload size={16} className="text-gray-500" /> T├®l├®verser des fichiers
                    </button>
                    <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition" onClick={() => emitDocumentAction('upload-folder')}>
                      <FolderUp size={16} className="text-gray-500" /> T├®l├®verser des dossiers
                    </button>

                    <hr className="my-2 border-gray-100" />

                    <p className="px-4 pb-1 text-xs font-semibold text-gray-400 uppercase tracking-wide">
                      Cr├®er un nouveau
                    </p>
                    <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition" onClick={() => emitDocumentAction('new-folder')}>
                      <FolderPlus size={16} className="text-gray-500" /> Nouveau dossier
                    </button>
                    <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition" onClick={() => emitDocumentAction('request-file')}>
                      <FileQuestion size={16} className="text-gray-500" /> Cr├®er une demande de fichier
                    </button>
                    <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition" onClick={() => emitDocumentAction('new-doc')}>
                      <FilePlus2 size={16} className="text-blue-500" /> Nouveau document
                    </button>
                    <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition" onClick={() => emitDocumentAction('new-text')}>
                      <FileText size={16} className="text-gray-500" /> Nouveau fichier texte
                    </button>
                    <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition" onClick={() => emitDocumentAction('new-whiteboard')}>
                      <LayoutIcon size={16} className="text-purple-500" /> Nouveau tableau blanc
                    </button>
                    <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition" onClick={() => emitDocumentAction('new-sheet')}>
                      <FileSpreadsheet size={16} className="text-green-500" /> Nouvelle feuille de calcul
                    </button>
                    <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition" onClick={() => emitDocumentAction('new-presentation')}>
                      <Presentation size={16} className="text-orange-500" /> Nouvelle pr├®sentation
                    </button>
                    <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition" onClick={() => emitDocumentAction('new-pdf-form')}>
                      <FileType2 size={16} className="text-red-500" /> Nouveau formulaire PDF
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
          <div className="flex items-center gap-4">
            <div className="relative" ref={notificationsRef}>
              <button
                type="button"
                onClick={() => setNotificationsOpen((v) => !v)}
                className="h-12 w-12 bg-white rounded-xl shadow-sm border relative grid place-items-center text-gray-600"
              >
                <Bell size={18} />
                {notifications.filter((n) => !n.isRead).length > 0 && (
                  <span className="absolute -top-1 -right-1 h-5 min-w-[20px] px-1 rounded-full bg-red-500 text-[10px] text-white grid place-items-center">
                    {notifications.filter((n) => !n.isRead).length > 99 ? '99+' : notifications.filter((n) => !n.isRead).length}
                  </span>
                )}
              </button>

              {notificationsOpen && (
                <div className="absolute right-0 top-full mt-2 w-96 max-w-[90vw] bg-white border border-gray-200 rounded-xl shadow-xl z-50 overflow-hidden">
                  <div className="px-4 py-3 border-b border-gray-100 flex items-center justify-between">
                    <p className="text-sm font-semibold text-gray-800">Notifications</p>
                    <div className="flex items-center gap-3">
                      {notifications.some((n) => !n.isRead) && (
                        <button
                          type="button"
                          onClick={handleMarkAllAsRead}
                          className="text-xs text-green-600 hover:underline"
                        >
                          Tout marquer lu
                        </button>
                      )}
                      <button
                        type="button"
                        onClick={loadNotifications}
                        className="text-xs text-[#2453d6] hover:underline"
                      >
                        Actualiser
                      </button>
                    </div>
                  </div>

                  {notificationsLoading ? (
                    <div className="px-4 py-6 text-sm text-gray-500">Chargement...</div>
                  ) : notifications.length === 0 ? (
                    <div className="px-4 py-6 text-sm text-gray-500">Aucune action en attente pour le moment.</div>
                  ) : (
                    <div className="max-h-80 overflow-auto">
                      {notifications.map((notification) => (
                        <button
                          key={notification.id}
                          type="button"
                          onClick={() => {
                            handleMarkAsRead(notification.id)
                            navigate(notification.actionUrl || '/workflows')
                            setNotificationsOpen(false)
                          }}
                          className={`w-full text-left px-4 py-3 border-b border-gray-100 hover:bg-gray-50 transition ${!notification.isRead ? 'bg-blue-50/50' : ''}`}
                        >
                          <div className="flex items-start gap-2">
                            {!notification.isRead && (
                              <span className="mt-1.5 h-2 w-2 rounded-full bg-blue-500 flex-shrink-0" />
                            )}
                            <div className="flex-1 min-w-0">
                              <p className={`text-sm ${!notification.isRead ? 'font-semibold' : 'font-medium'} text-gray-800`}>{notification.title}</p>
                              <p className="text-xs text-gray-600 mt-1">{notification.description}</p>
                              <p className="text-[11px] text-gray-400 mt-1">{formatDate(notification.createdAt)}</p>
                            </div>
                          </div>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="relative" ref={userMenuRef}>
              <button
                type="button"
                onClick={() => setUserMenuOpen((v) => !v)}
                className="h-12 bg-white rounded-xl shadow-sm border px-3 flex items-center gap-2 text-gray-700 hover:bg-gray-50 transition"
              >
                <div className="h-8 w-8 rounded-full bg-[#2453d6]/10 text-[#2453d6] overflow-hidden flex items-center justify-center font-semibold text-xs">
                  {user?.avatar ? (
                    <img src={toAvatarUrl(user.avatar)} alt="Avatar" className="h-full w-full object-cover" />
                  ) : (
                    (user?.fullName?.slice(0, 2).toUpperCase() || 'AD')
                  )}
                </div>
                <ChevronDown size={16} className="text-gray-500" />
              </button>

              {userMenuOpen && (
                <div className="absolute right-0 top-full mt-2 w-64 bg-white border border-gray-200 rounded-xl shadow-xl z-50 overflow-hidden py-2">
                  <div className="px-4 py-3 border-b border-gray-100">
                    <p className="text-sm font-semibold text-gray-800 truncate">{user?.fullName || 'Utilisateur'}</p>
                    <p className="text-xs text-gray-500 truncate">{user?.email || 'user@example.com'}</p>
                  </div>

                  <button
                    className="w-full flex items-center gap-3 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition"
                    onClick={() => {
                      navigate('/profile')
                      setUserMenuOpen(false)
                    }}
                  >
                    <UserCircle size={16} className="text-gray-500" /> Mon profil
                  </button>

                  <hr className="my-2 border-gray-100" />

                  <button
                    className="w-full flex items-center gap-3 px-4 py-2 text-sm text-red-600 hover:bg-red-50 transition"
                    onClick={handleLogout}
                  >
                    <LogOut size={16} /> D├®connexion
                  </button>
                </div>
              )}
            </div>

          </div>
        </header>

        <div className="px-8 pb-8">
          <Outlet />
        </div>
      </main>

      {/* Chat en temps r├®el */}
      <ChatPanel />
    </div>
  )
}

export default Layout

import { useEffect, useMemo, useState } from 'react'
import { CheckCircle2, Download, FileText, Filter, Search } from 'lucide-react'
import JSZip from 'jszip'
import api from '../services/api'
import { ActRequestDetails, fetchActRequestDetails, fetchActRequests, markActRequestAsTreated, startActRequestProcessing } from '../services/documents'
import { tokenStore } from '../services/tokenStore'
import { DocumentItem } from '../types/document'

function normalizeSubEntity(value?: string | null): string {
  return String(value || '').trim().toUpperCase()
}

function isActRequestDocument(doc: DocumentItem): boolean {
  const normalizedType = String(doc.type || '').trim().toLowerCase()
  if (normalizedType === 'request' || normalizedType === 'demande_acte') {
    return true
  }

  const title = String(doc.title || '').toLowerCase()
  const description = String(doc.description || '').toLowerCase()
  return title.includes('demande') || description.includes('demande')
}

type ParsedRequestMeta = {
  applicant: { fullName: string; email: string; phone?: string }
  applicantFieldValues: Record<string, string>
  receivedDocuments: Array<{ originalName: string; storedPath: string; requiredDocumentLabel?: string }>
}

function normalizeKey(value: string): string {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim()
}

function parseRequestMeta(description?: string | null): ParsedRequestMeta {
  const raw = String(description || '')
  const marker = 'ACT_REQUEST_META::'
  const markerIndex = raw.indexOf(marker)

  if (markerIndex >= 0) {
    const jsonPart = raw.slice(markerIndex + marker.length).trim()
    try {
      const parsed = JSON.parse(jsonPart) as Record<string, any>
      const applicantFieldValues = Object.entries((parsed?.applicantFieldValues || {}) as Record<string, unknown>)
        .reduce((acc, [key, value]) => {
          const label = String(key || '').trim()
          if (!label) return acc
          acc[label] = String(value || '').trim()
          return acc
        }, {} as Record<string, string>)

      const receivedDocuments = Array.isArray(parsed?.receivedDocuments)
        ? parsed.receivedDocuments
          .map((item: any) => ({
            originalName: String(item?.originalName || '').trim(),
            storedPath: String(item?.storedPath || '').trim(),
            requiredDocumentLabel: String(item?.requiredDocumentLabel || '').trim() || undefined,
          }))
          .filter((item: { originalName: string; storedPath: string }) => item.originalName || item.storedPath)
        : []

      return {
        applicant: {
          fullName: String(parsed?.applicant?.fullName || '').trim(),
          email: String(parsed?.applicant?.email || '').trim(),
          phone: String(parsed?.applicant?.phone || '').trim() || undefined,
        },
        applicantFieldValues,
        receivedDocuments,
      }
    } catch {
      // Ignore and fallback to empty values.
    }
  }

  return {
    applicant: { fullName: '', email: '', phone: undefined },
    applicantFieldValues: {},
    receivedDocuments: [],
  }
}

function pickFieldByLabel(values: Record<string, string>, acceptedLabels: string[]): string {
  const normalizedTargets = acceptedLabels.map(normalizeKey)
  for (const [label, value] of Object.entries(values)) {
    if (normalizedTargets.some((target) => normalizeKey(label).includes(target))) {
      return String(value || '').trim()
    }
  }
  return ''
}

function isFieldDisplayedInTable(label: string): boolean {
  const normalized = normalizeKey(label)
  if (!normalized) return false
  return [
    'nom',
    'prenom',
    'email',
    'mail',
    'telephone',
    'phone',
    'mobile',
    'matricule',
  ].some((token) => normalized.includes(token))
}

function mapRequestStatus(status: string): { label: string; className: string } {
  const normalized = String(status || '').trim().toLowerCase()
  if (normalized === 'draft') {
    return { label: 'En attente', className: 'bg-amber-50 text-amber-700 border border-amber-100' }
  }
  if (normalized === 'active' || normalized === 'pending_signature') {
    return { label: 'En cours', className: 'bg-blue-50 text-blue-700 border border-blue-100' }
  }
  if (normalized === 'signed') {
    return { label: 'Signe', className: 'bg-indigo-50 text-indigo-700 border border-indigo-100' }
  }
  if (normalized === 'archived') {
    return { label: 'Trait├®', className: 'bg-emerald-50 text-emerald-700 border border-emerald-100' }
  }
  return { label: status || '-', className: 'bg-gray-50 text-gray-700 border border-gray-100' }
}

function resolveUploadUrl(storedPath: string): string {
  const normalizedPath = String(storedPath || '').trim()
  if (!normalizedPath) return ''
  if (/^https?:\/\//i.test(normalizedPath)) return normalizedPath
  const origin = new URL(String(api.defaults.baseURL || window.location.origin), window.location.origin).origin
  return new URL(normalizedPath.startsWith('/') ? normalizedPath : `/${normalizedPath}`, origin).toString()
}

function safeFileName(value: string, fallback = 'piece_jointe'): string {
  const trimmed = String(value || '').trim()
  if (!trimmed) return fallback
  return trimmed.replace(/[\\/:*?"<>|]+/g, '_')
}

function ActRequests() {
  const [documents, setDocuments] = useState<DocumentItem[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [search, setSearch] = useState('')
  const [subEntityFilter, setSubEntityFilter] = useState('all')
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null)
  const [details, setDetails] = useState<ActRequestDetails | null>(null)
  const [detailsLoading, setDetailsLoading] = useState(false)
  const [detailsError, setDetailsError] = useState<string | null>(null)
  const [zipLoadingById, setZipLoadingById] = useState<Record<string, boolean>>({})
  const [treatLoadingById, setTreatLoadingById] = useState<Record<string, boolean>>({})
  const [processingStartedById, setProcessingStartedById] = useState<Record<string, boolean>>({})
  const [viewMode, setViewMode] = useState<'in-progress' | 'treated'>('in-progress')

  const loadData = async () => {
    setLoading(true)
    setError(null)

    try {
      const data = await fetchActRequests(1, 200)
      setDocuments(Array.isArray(data) ? data : [])
    } catch (err: any) {
      setError(err?.response?.data?.message || 'Impossible de charger les demandes d\'actes.')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    void loadData()
  }, [])

  // Business filtering is enforced by API; keep a light fallback filter for compatibility.
  const actRequests = useMemo(() => documents.filter(isActRequestDocument), [documents])

  const subEntities = useMemo(() => {
    const unique = Array.from(
      new Set(
        actRequests
          .map((doc) => normalizeSubEntity(doc.subEntityCode))
          .filter((code) => code.length > 0),
      ),
    )
    return unique.sort((a, b) => a.localeCompare(b))
  }, [actRequests])

  const filtered = useMemo(() => {
    const term = search.trim().toLowerCase()

    return actRequests.filter((doc) => {
      const subEntity = normalizeSubEntity(doc.subEntityCode)
      const keepByEntity = subEntityFilter === 'all' || subEntity === subEntityFilter
      if (!keepByEntity) return false

      if (!term) return true

      return [
        doc.title,
        doc.description,
        doc.status,
        doc.type,
        doc.documentNumber,
        subEntity,
      ]
        .map((value) => String(value || '').toLowerCase())
        .join(' ')
        .includes(term)
    })
  }, [actRequests, search, subEntityFilter])

  const tableRows = useMemo(() => {
    return filtered.map((doc) => {
      const parsed = parseRequestMeta(doc.description)
      const matricule = pickFieldByLabel(parsed.applicantFieldValues, ['matricule'])
      const phoneFromFields = pickFieldByLabel(parsed.applicantFieldValues, ['telephone', 'tel', 'phone', 'mobile'])
      const statusView = mapRequestStatus(doc.status)
      return {
        id: doc.id,
        doc,
        actName: doc.title || '-',
        applicantName: parsed.applicant.fullName || '-',
        email: parsed.applicant.email || '-',
        matricule: matricule || '-',
        phone: parsed.applicant.phone || phoneFromFields || '-',
        attachments: parsed.receivedDocuments,
        createdAtLabel: new Date(doc.createdAt).toLocaleString('fr-FR'),
        statusLabel: statusView.label,
        statusClassName: statusView.className,
      }
    })
  }, [filtered])

  const stats = useMemo(() => {
    const done = filtered.filter((doc) => String(doc.status || '').trim().toLowerCase() === 'archived').length
    const waiting = Math.max(0, filtered.length - done)
    return {
      total: filtered.length,
      waiting,
      done,
    }
  }, [filtered])

  const openDetails = async (id: string) => {
    setSelectedRequestId(id)
    setDetails(null)
    setDetailsError(null)
    setDetailsLoading(true)
    try {
      const data = await fetchActRequestDetails(id)
      setDetails(data)
    } catch (err: any) {
      setDetailsError(err?.response?.data?.message || 'Impossible de charger le d├®tail de la demande.')
    } finally {
      setDetailsLoading(false)
    }
  }

  const closeDetailsModal = () => {
    setSelectedRequestId(null)
    setDetails(null)
    setDetailsError(null)
  }

  const downloadAttachmentsZip = async (row: (typeof tableRows)[number]) => {
    const files = row.attachments.filter((item) => String(item.storedPath || '').trim())
    if (files.length === 0) {
      setError('Aucun fichier joint ├á zipper pour cette demande.')
      return
    }

    setZipLoadingById((prev) => ({ ...prev, [row.id]: true }))
    try {
      const zip = new JSZip()
      const token = tokenStore.getAccessToken()

      for (const [index, file] of files.entries()) {
        const url = resolveUploadUrl(file.storedPath)
        if (!url) continue

        const response = await fetch(url, {
          headers: token ? { Authorization: `Bearer ${token}` } : undefined,
        })
        if (!response.ok) {
          throw new Error(`T├®l├®chargement impossible pour ${file.originalName || file.storedPath}`)
        }
        const blob = await response.blob()
        const fallback = `piece_jointe_${index + 1}`
        zip.file(safeFileName(file.originalName || file.storedPath, fallback), blob)
      }

      const zipBlob = await zip.generateAsync({ type: 'blob' })
      const objectUrl = URL.createObjectURL(zipBlob)
      const link = document.createElement('a')
      link.href = objectUrl
      link.download = `${safeFileName(row.actName, 'demande_acte')}-${row.id.slice(0, 8)}.zip`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(objectUrl)

      const processingResult = await startActRequestProcessing(row.id)
      setDocuments((prev) => prev.map((item) => (item.id === row.id ? { ...item, status: processingResult.status as any } : item)))
      setProcessingStartedById((prev) => ({ ...prev, [row.id]: true }))
    } catch (err: any) {
      setError(err?.message || 'Impossible de g├®n├®rer le ZIP des pi├¿ces jointes.')
    } finally {
      setZipLoadingById((prev) => ({ ...prev, [row.id]: false }))
    }
  }

  const markAsTreated = async (rowId: string) => {
    setError(null)
    setTreatLoadingById((prev) => ({ ...prev, [rowId]: true }))
    try {
      const result = await markActRequestAsTreated(rowId)
      setDocuments((prev) => prev.map((item) => (item.id === rowId ? { ...item, status: result.status as any } : item)))
    } catch (err: any) {
      setError(err?.response?.data?.message || 'Impossible de marquer la demande comme traitee.')
    } finally {
      setTreatLoadingById((prev) => ({ ...prev, [rowId]: false }))
    }
  }

  const rowsByMode = useMemo(() => {
    if (viewMode === 'treated') {
      return tableRows.filter((row) => String(row.doc.status || '').trim().toLowerCase() === 'archived')
    }
    return tableRows.filter((row) => String(row.doc.status || '').trim().toLowerCase() !== 'archived')
  }, [tableRows, viewMode])

  return (
    <div className="space-y-5">
      <div className="bg-white border border-gray-100 rounded-2xl p-5 shadow-sm">
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-xl bg-blue-50 flex items-center justify-center">
              <FileText size={18} className="text-[#2453d6]" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-gray-800">Demandes d'actes</h2>
              <p className="text-xs text-gray-500">
                Les demandes sont recues par administration puis orientees vers l'entite sous tutelle (code entite).
              </p>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2 text-xs">
            <span className="inline-flex px-2.5 py-1 rounded-full bg-blue-50 text-blue-700 border border-blue-100">
              Total: {stats.total}
            </span>
            <button
              type="button"
              onClick={() => setViewMode('in-progress')}
              className={`inline-flex px-2.5 py-1 rounded-full border ${viewMode === 'in-progress' ? 'bg-amber-100 text-amber-800 border-amber-300' : 'bg-amber-50 text-amber-700 border-amber-100 hover:bg-amber-100'}`}
            >
              A traiter: {stats.waiting}
            </button>
            <button
              type="button"
              onClick={() => setViewMode('treated')}
              className={`inline-flex px-2.5 py-1 rounded-full border ${viewMode === 'treated' ? 'bg-emerald-100 text-emerald-800 border-emerald-300' : 'bg-emerald-50 text-emerald-700 border-emerald-100 hover:bg-emerald-100'}`}
            >
              Traitees: {stats.done}
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white border border-gray-100 rounded-2xl p-4 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <div className="relative">
            <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Rechercher une demande d'acte..."
              className="w-full border border-gray-300 rounded-lg pl-9 pr-3 py-2 text-sm outline-none focus:ring-2 focus:ring-[#2453d6]/30"
            />
          </div>

          <div className="relative">
            <Filter size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
            <select
              value={subEntityFilter}
              onChange={(e) => setSubEntityFilter(e.target.value)}
              className="w-full border border-gray-300 rounded-lg pl-9 pr-3 py-2 text-sm outline-none focus:ring-2 focus:ring-[#2453d6]/30 appearance-none bg-white"
            >
              <option value="all">Toutes les entites sous tutelle</option>
              {subEntities.map((code) => (
                <option key={code} value={code}>{code}</option>
              ))}
            </select>
          </div>
        </div>
      </div>

      <div className="bg-white border border-gray-100 rounded-2xl shadow-sm overflow-hidden">
        {error && <div className="p-4 text-sm text-red-700 bg-red-50 border-b border-red-100">{error}</div>}

        <table className="w-full text-sm">
          <thead className="bg-gray-50 text-gray-600 text-xs uppercase">
            <tr>
              <th className="px-4 py-3 text-left">Nom de l'acte</th>
              <th className="px-4 py-3 text-left">Nom du demandeur</th>
              <th className="px-4 py-3 text-left">Email</th>
              <th className="px-4 py-3 text-left">Matricule</th>
              <th className="px-4 py-3 text-left">Telephone</th>
              <th className="px-4 py-3 text-left">Fichier joint</th>
              <th className="px-4 py-3 text-left">Date</th>
              <th className="px-4 py-3 text-left">Statut</th>
              <th className="px-4 py-3 text-left">Action</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td className="px-4 py-6 text-gray-500" colSpan={9}>Chargement...</td>
              </tr>
            ) : rowsByMode.length === 0 ? (
              <tr>
                <td className="px-4 py-6 text-gray-500" colSpan={9}>
                  {viewMode === 'treated' ? 'Aucune demande traitee.' : 'Aucune demande d\'acte en cours.'}
                </td>
              </tr>
            ) : (
              rowsByMode.map((row) => {
                const isProcessing = String(row.doc.status || '').trim().toLowerCase() === 'active' || Boolean(processingStartedById[row.id])
                const isSigned = String(row.doc.status || '').trim().toLowerCase() === 'signed'
                return (
                  <tr key={row.id} className="border-t border-gray-100 hover:bg-gray-50">
                    <td className="px-4 py-3">
                      <p className="font-semibold text-gray-800">{row.actName}</p>
                      <button
                        type="button"
                        onClick={() => openDetails(row.id)}
                        className="text-[11px] text-indigo-700 hover:text-indigo-900 mt-1"
                      >
                        Voir d├®tail
                      </button>
                    </td>
                    <td className="px-4 py-3 text-gray-700">{row.applicantName}</td>
                    <td className="px-4 py-3 text-gray-700">{row.email}</td>
                    <td className="px-4 py-3 text-gray-700">{row.matricule}</td>
                    <td className="px-4 py-3 text-gray-700">{row.phone}</td>
                    <td className="px-4 py-3">
                      <button
                        type="button"
                        onClick={() => downloadAttachmentsZip(row)}
                        disabled={zipLoadingById[row.id] || row.attachments.length === 0}
                        className={`inline-flex items-center gap-1 px-2 py-1 rounded text-xs border disabled:opacity-60 ${
                          isProcessing
                            ? 'border-emerald-200 text-emerald-700 bg-emerald-50 hover:bg-emerald-100'
                            : 'border-orange-200 text-orange-700 hover:bg-orange-50'
                        }`}
                      >
                        <Download size={12} />
                        {zipLoadingById[row.id] ? 'Zippage...' : (isProcessing ? 'ZIP t├®l├®charg├®' : `ZIP (${row.attachments.length})`)}
                      </button>
                    </td>
                    <td className="px-4 py-3 text-gray-600">{row.createdAtLabel}</td>
                    <td className="px-4 py-3">
                      <span className={`inline-flex px-2 py-1 rounded-full text-xs ${row.statusClassName}`}>
                        {row.statusLabel}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      {viewMode === 'in-progress' && isSigned ? (
                        <button
                          type="button"
                          onClick={() => markAsTreated(row.id)}
                          disabled={Boolean(treatLoadingById[row.id])}
                          className="inline-flex items-center gap-1 px-2 py-1 rounded text-xs border border-emerald-200 text-emerald-700 hover:bg-emerald-50 disabled:opacity-60"
                        >
                          <CheckCircle2 size={12} />
                          {treatLoadingById[row.id] ? 'Traitement...' : 'Traiter'}
                        </button>
                      ) : (
                        <span className="text-xs text-gray-400">-</span>
                      )}
                    </td>
                  </tr>
                )
              })
            )}
          </tbody>
        </table>
      </div>

      {selectedRequestId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <button
            type="button"
            aria-label="Fermer la modale"
            onClick={closeDetailsModal}
            className="absolute inset-0 bg-black/45"
          />

          <div className="relative w-full max-w-4xl max-h-[88vh] overflow-y-auto bg-white border border-gray-200 rounded-2xl shadow-2xl p-5 space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-base font-bold text-gray-800">D├®tail de la demande</h3>
              <button
                type="button"
                onClick={closeDetailsModal}
                className="text-xs text-gray-500 hover:text-gray-700"
              >
                Fermer
              </button>
            </div>

            {detailsLoading && <p className="text-sm text-gray-500">Chargement du d├®tail...</p>}
            {detailsError && <p className="text-sm text-red-700">{detailsError}</p>}

            {details && !detailsLoading && !detailsError && (
              <div className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-sm">
                  <div className="rounded-lg border border-gray-200 bg-gray-50 p-3">
                    <p className="text-xs text-gray-500">Acte demand├®</p>
                    <p className="font-semibold text-gray-800 mt-1">{details.title || '-'}</p>
                    <p className="text-xs text-gray-600 mt-1">Entit├®: {details.subEntityCode || '-'}</p>
                  </div>
                  <div className="rounded-lg border border-gray-200 bg-gray-50 p-3">
                    <p className="text-xs text-gray-500">Compl├®tude du dossier</p>
                    <p className="font-semibold text-gray-800 mt-1">
                      {details.completeness.requiredReceived}/{details.completeness.requiredTotal} pi├¿ce(s) exig├®e(s)
                    </p>
                    <p className="text-xs text-gray-600 mt-1">{details.completeness.receivedTotal} fichier(s) re├ºu(s)</p>
                  </div>
                </div>

                <div className="rounded-lg border border-gray-200 bg-gray-50 p-3">
                  <p className="text-xs font-semibold text-gray-700">Champs saisis non affich├®s dans le tableau</p>
                  {Object.entries(details.applicantFieldValues || {})
                    .filter(([label, value]) => !isFieldDisplayedInTable(label) && String(value || '').trim())
                    .length === 0 ? (
                      <p className="text-sm text-gray-500 mt-2">Aucun champ compl├®mentaire renseign├®.</p>
                    ) : (
                      <div className="mt-2 grid grid-cols-1 md:grid-cols-2 gap-2">
                        {Object.entries(details.applicantFieldValues || {})
                          .filter(([label, value]) => !isFieldDisplayedInTable(label) && String(value || '').trim())
                          .map(([label, value]) => (
                            <div key={label} className="rounded-md border border-gray-200 bg-white px-3 py-2">
                              <p className="text-[11px] text-gray-500">{label}</p>
                              <p className="text-sm text-gray-800 mt-0.5 whitespace-pre-wrap">{value || '-'}</p>
                            </div>
                          ))}
                      </div>
                    )}
                </div>

                {details.note && (
                  <div className="rounded-lg border border-gray-200 bg-gray-50 p-3">
                    <p className="text-xs text-gray-500">Observation usager</p>
                    <p className="text-sm text-gray-700 mt-1 whitespace-pre-wrap">{details.note}</p>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

export default ActRequests

import { MouseEvent, useEffect, useMemo, useRef, useState } from 'react';
import {
  Folder, FileText, MoreHorizontal, UserPlus,
  Star, Info, Tag, Pencil, FolderInput,
  Bell, MonitorDown, Download, Trash2,
} from 'lucide-react';
import { DocumentItem } from '../types/document';
import {
  fetchDocuments,
  createDocument,
  deleteDocument,
  updateDocument,
  shareDocument,
  fetchMyDocumentPreferences,
  updateDocumentFavoritePreference,
  updateDocumentLabelCodesPreference,
} from '../services/documents';
import { fetchRecipientAdministrations } from '../services/administration';
import { RecipientAdministration } from '../types/administration';

function Documents() {
  const [documents, setDocuments] = useState<DocumentItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [openActionsId, setOpenActionsId] = useState<string | null>(null);
  const [folderTabs, setFolderTabs] = useState<string[]>([]);
  const [activeFolderTab, setActiveFolderTab] = useState<string | null>(null);
  const [activeSubTab, setActiveSubTab] = useState<'all' | 'favorites' | 'labels'>('all');
  const [favoriteDocumentIds, setFavoriteDocumentIds] = useState<string[]>([]);
  const [documentLabelCodes, setDocumentLabelCodes] = useState<Record<string, string[]>>({});
  const [labelSearchCode, setLabelSearchCode] = useState('');
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [shareTarget, setShareTarget] = useState<DocumentItem | null>(null);
  const [shareMode, setShareMode] = useState<'internal' | 'external' | 'recipient_administration'>('internal');
  const [shareInternalRecipient, setShareInternalRecipient] = useState('');
  const [shareExternalEmail, setShareExternalEmail] = useState('');
  const [recipientAdministrations, setRecipientAdministrations] = useState<RecipientAdministration[]>([]);
  const [shareRecipientAdministrationId, setShareRecipientAdministrationId] = useState('');
  const [shareApplicantFullName, setShareApplicantFullName] = useState('');
  const [shareApplicantMatricule, setShareApplicantMatricule] = useState('');
  const [shareApplicantEmail, setShareApplicantEmail] = useState('');
  const [sharePermission, setSharePermission] = useState<'lecture' | 'modification'>('lecture');
  const [shareHasDelay, setShareHasDelay] = useState(false);
  const [shareDelayValue, setShareDelayValue] = useState('24');
  const [shareDelayUnit, setShareDelayUnit] = useState<'hours' | 'days'>('hours');
  const [shareStatus, setShareStatus] = useState<{ type: 'success' | 'error'; message: string } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);

  const normalizeLabelCode = (value: string) => value.trim().toUpperCase();

  const isFavoriteDocument = (docId: string) => favoriteDocumentIds.includes(docId);

  const parseLabelCodes = (value: string) => Array.from(new Set(
    value
      .split(',')
      .map((item) => normalizeLabelCode(item))
      .filter((item) => item.length > 0),
  ));

  const isFolder = (doc: DocumentItem) => doc.type === 'folder' || doc.description === '[folder]';

  const getParentFolderName = (doc: DocumentItem): string | null => {
    if (isFolder(doc)) return null;
    if (!doc.description) return null;
    const match = doc.description.match(/^Dossier:\s*(.+)$/i);
    return match?.[1]?.trim() || null;
  };

  const openFileInOnlyOffice = (doc: DocumentItem) => {
    const onlyOfficeBaseUrl = (localStorage.getItem('oo_url') || '').replace(/\/$/, '');
    if (!onlyOfficeBaseUrl) {
      setError('URL OnlyOffice non configur├®e. Configurez-la dans lÔÇÖonglet Administration > OnlyOffice.');
      return;
    }

    const readerUrl = `${onlyOfficeBaseUrl}/web-apps/apps/documenteditor/main/index.html?title=${encodeURIComponent(doc.title)}&mode=view`;
    window.open(readerUrl, '_blank', 'noopener,noreferrer');
  };

  const handleDocumentDoubleClick = (doc: DocumentItem, event: MouseEvent<HTMLTableRowElement>) => {
    const target = event.target as HTMLElement | null;
    if (target?.closest('[data-row-actions="true"]')) return;

    if (isFolder(doc)) {
      setFolderTabs((prev) => (prev.includes(doc.title) ? prev : [...prev, doc.title]));
      setActiveFolderTab(doc.title);
      return;
    }

    openFileInOnlyOffice(doc);
  };

  const loadDocuments = async () => {
    setLoading(true);
    setError(null);
    try {
      const [data, preferences] = await Promise.all([
        fetchDocuments(),
        fetchMyDocumentPreferences(),
      ]);
      setDocuments(Array.isArray(data) ? data : []);

      const nextFavoriteIds = preferences
        .filter((item) => Boolean(item?.isFavorite) && String(item?.documentId || '').trim())
        .map((item) => String(item.documentId));
      setFavoriteDocumentIds(Array.from(new Set(nextFavoriteIds)));

      const nextLabelCodes = preferences.reduce((acc, item) => {
        const docId = String(item?.documentId || '').trim();
        if (!docId) return acc;
        const codes = Array.isArray(item?.labelCodes)
          ? item.labelCodes.map((code) => normalizeLabelCode(code)).filter(Boolean)
          : [];
        if (codes.length > 0) {
          acc[docId] = Array.from(new Set(codes));
        }
        return acc;
      }, {} as Record<string, string[]>);
      setDocumentLabelCodes(nextLabelCodes);
    } catch (err) {
      console.error(err);
      setError('Impossible de charger les documents.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadDocuments();
  }, []);

  useEffect(() => {
    const loadRecipients = async () => {
      try {
        const data = await fetchRecipientAdministrations();
        setRecipientAdministrations((Array.isArray(data) ? data : []).filter((item) => item.isActive));
      } catch {
        setRecipientAdministrations([]);
      }
    };
    void loadRecipients();
  }, []);

  const handleDelete = async (id: string) => {
    if (!window.confirm('Supprimer ce document ?')) return;
    try {
      await deleteDocument(id);
      setDocuments((prev) => prev.filter((doc) => doc.id !== id));
      setOpenActionsId(null);
    } catch (err) {
      console.error(err);
      setError('Impossible de supprimer le document.');
    }
  };

  const updateDocumentLocally = (id: string, updater: (doc: DocumentItem) => DocumentItem) => {
    setDocuments((prev) => prev.map((doc) => (doc.id === id ? updater(doc) : doc)));
  };

  const handleRename = async (doc: DocumentItem) => {
    const newTitle = window.prompt('Nouveau nom', doc.title);
    if (!newTitle || !newTitle.trim() || newTitle.trim() === doc.title) return;

    try {
      const updated = await updateDocument(doc.id, { title: newTitle.trim() });
      updateDocumentLocally(doc.id, () => updated);
      if (isFolder(doc) && doc.title !== updated.title) {
        setFolderTabs((prev) => prev.map((tab) => (tab === doc.title ? updated.title : tab)));
        setActiveFolderTab((prev) => (prev === doc.title ? updated.title : prev));
      }
      setOpenActionsId(null);
    } catch (err) {
      console.error(err);
      setError('Impossible de renommer cet ├®l├®ment.');
    }
  };

  const handleMove = async (doc: DocumentItem) => {
    const destination = window.prompt('D├®placer vers (nom du dossier)');
    if (!destination || !destination.trim()) return;

    try {
      const nextDescription = `Dossier: ${destination.trim()}`;
      const updated = await updateDocument(doc.id, { description: nextDescription });
      updateDocumentLocally(doc.id, () => updated);
      setOpenActionsId(null);
    } catch (err) {
      console.error(err);
      setError('Impossible de d├®placer cet ├®l├®ment.');
    }
  };

  const openShareModal = (doc: DocumentItem) => {
    setShareTarget(doc);
    setShareMode('internal');
    setShareInternalRecipient('');
    setShareExternalEmail('');
    setShareRecipientAdministrationId('');
    setShareApplicantFullName('');
    setShareApplicantMatricule('');
    setShareApplicantEmail('');
    setSharePermission('lecture');
    setShareHasDelay(false);
    setShareDelayValue('24');
    setShareDelayUnit('hours');
    setShareStatus(null);
    setIsShareModalOpen(true);
    setOpenActionsId(null);
  };

  const closeShareModal = () => {
    setIsShareModalOpen(false);
    setShareStatus(null);
  };

  const buildShareDelayLabel = () => {
    if (!shareHasDelay) return '';

    const parsedValue = Number(shareDelayValue);
    if (!Number.isFinite(parsedValue) || parsedValue <= 0) return '';

    const expiresAt = new Date();
    if (shareDelayUnit === 'hours') {
      expiresAt.setHours(expiresAt.getHours() + parsedValue);
    } else {
      expiresAt.setDate(expiresAt.getDate() + parsedValue);
    }

    return `Valide jusqu'au ${expiresAt.toLocaleString('fr-FR')}`;
  };

  const handleSubmitShare = async () => {
    if (!shareTarget) return;

    const delayLabel = buildShareDelayLabel();
    if (shareHasDelay && !delayLabel) {
      setShareStatus({ type: 'error', message: 'Veuillez renseigner un d├®lai valide (nombre strictement positif).' });
      return;
    }

    const delayValueNum = Number(shareDelayValue);

    if (shareMode === 'internal') {
      if (!shareInternalRecipient.trim()) {
        setShareStatus({ type: 'error', message: 'Veuillez renseigner un utilisateur, un service ou un groupe interne.' });
        return;
      }

      try {
        await shareDocument(shareTarget.id, {
          mode: 'internal',
          recipientName: shareInternalRecipient.trim(),
          recipientEmail: shareInternalRecipient.includes('@') ? shareInternalRecipient.trim() : undefined,
          permission: sharePermission,
          hasDelay: shareHasDelay,
          delayValue: shareHasDelay ? delayValueNum : undefined,
          delayUnit: shareHasDelay ? shareDelayUnit : undefined,
        });
        setShareStatus({
          type: 'success',
          message: `Le fichier ┬½ ${shareTarget.title} ┬╗ a ├®t├® partag├® en interne avec ┬½ ${shareInternalRecipient.trim()} ┬╗ (${sharePermission}).${delayLabel ? ` ${delayLabel}.` : ''}`,
        });
      } catch (err: any) {
        setShareStatus({ type: 'error', message: err?.response?.data?.message || '├ëchec du partage interne.' });
      }
      return;
    }

    if (shareMode === 'recipient_administration') {
      const applicantEmail = shareApplicantEmail.trim();
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!shareRecipientAdministrationId) {
        setShareStatus({ type: 'error', message: 'Veuillez s├®lectionner une administration destinataire.' });
        return;
      }
      if (!shareApplicantFullName.trim() || !shareApplicantMatricule.trim() || !applicantEmail) {
        setShareStatus({ type: 'error', message: 'Nom et pr├®noms, matricule et email sont obligatoires.' });
        return;
      }
      if (!emailRegex.test(applicantEmail)) {
        setShareStatus({ type: 'error', message: 'Veuillez saisir une adresse email usager valide.' });
        return;
      }

      try {
        const selectedAdministration = recipientAdministrations.find((item) => item.id === shareRecipientAdministrationId);
        await shareDocument(shareTarget.id, {
          mode: 'recipient_administration',
          recipientAdministrationId: shareRecipientAdministrationId,
          applicantFullName: shareApplicantFullName.trim(),
          applicantMatricule: shareApplicantMatricule.trim(),
          applicantEmail,
          recipientName: selectedAdministration?.name,
          permission: sharePermission,
          hasDelay: shareHasDelay,
          delayValue: shareHasDelay ? delayValueNum : undefined,
          delayUnit: shareHasDelay ? shareDelayUnit : undefined,
        });
        setShareStatus({
          type: 'success',
          message: `Le document ┬½ ${shareTarget.title} ┬╗ a ├®t├® partag├® ├á l'administration destinataire s├®lectionn├®e.${delayLabel ? ` ${delayLabel}.` : ''}`,
        });
      } catch (err: any) {
        setShareStatus({ type: 'error', message: err?.response?.data?.message || '├ëchec du partage vers administration destinataire.' });
      }
      return;
    }

    const email = shareExternalEmail.trim();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      setShareStatus({ type: 'error', message: 'Veuillez saisir une adresse email valide.' });
      return;
    }

    try {
      await shareDocument(shareTarget.id, {
        mode: 'external',
        recipientEmail: email,
        permission: sharePermission,
        hasDelay: shareHasDelay,
        delayValue: shareHasDelay ? delayValueNum : undefined,
        delayUnit: shareHasDelay ? shareDelayUnit : undefined,
      });
      setShareStatus({
        type: 'success',
        message: `Le lien de partage externe du fichier ┬½ ${shareTarget.title} ┬╗ a ├®t├® envoy├® ├á ${email}.${delayLabel ? ` ${delayLabel}.` : ''}`,
      });
    } catch (err: any) {
      setShareStatus({ type: 'error', message: err?.response?.data?.message || '├ëchec du partage externe.' });
    }
  };

  const handleFavorite = async (doc: DocumentItem) => {
    const shouldFavorite = !isFavoriteDocument(doc.id);
    try {
      const response = await updateDocumentFavoritePreference(doc.id, shouldFavorite);
      setFavoriteDocumentIds((prev) => (
        response.isFavorite
          ? Array.from(new Set([...prev, doc.id]))
          : prev.filter((id) => id !== doc.id)
      ));
    } catch (err) {
      console.error(err);
      setError('Impossible de mettre a jour les favoris.');
    }
    setOpenActionsId(null);
  };

  const handleDetails = (doc: DocumentItem) => {
    window.alert(`D├®tails : ${doc.title}\nCr├®├® le: ${new Date(doc.createdAt).toLocaleString('fr-FR')}`);
    setOpenActionsId(null);
  };

  const handleLabels = async (doc: DocumentItem) => {
    const currentCodes = documentLabelCodes[doc.id] || [];
    const input = window.prompt(
      `Codes etiquette pour ┬½ ${doc.title} ┬╗ (separes par des virgules)`,
      currentCodes.join(', '),
    );

    if (input === null) {
      setOpenActionsId(null);
      return;
    }

    const nextCodes = parseLabelCodes(input);
    try {
      const response = await updateDocumentLabelCodesPreference(doc.id, nextCodes);
      const persistedCodes = Array.isArray(response.labelCodes)
        ? response.labelCodes.map((code) => normalizeLabelCode(code)).filter(Boolean)
        : [];

      setDocumentLabelCodes((prev) => {
        const next = { ...prev };
        if (persistedCodes.length === 0) {
          delete next[doc.id];
          return next;
        }
        next[doc.id] = Array.from(new Set(persistedCodes));
        return next;
      });
    } catch (err) {
      console.error(err);
      setError('Impossible de mettre a jour les etiquettes.');
    }
    setOpenActionsId(null);
  };

  const handleReminder = (doc: DocumentItem) => {
    window.alert(`Rappel configur├® pour ┬½ ${doc.title} ┬╗`);
    setOpenActionsId(null);
  };

  const handleEditLocally = (doc: DocumentItem) => {
    window.alert(`Ouverture locale de ┬½ ${doc.title} ┬╗`);
    setOpenActionsId(null);
  };

  const handleDownload = (doc: DocumentItem) => {
    window.alert(`T├®l├®chargement de ┬½ ${doc.title} ┬╗ en cours...`);
    setOpenActionsId(null);
  };

  const addDocumentLocally = (doc: DocumentItem) => {
    setDocuments((prev) => [doc, ...prev]);
  };

  const createBasicDocument = async (title: string, type: string, parentFolderName?: string) => {
    const newDoc = await createDocument({
      title,
      description: type === 'folder' ? '[folder]' : parentFolderName ? `Dossier: ${parentFolderName}` : undefined,
    });
    addDocumentLocally({ ...newDoc, type });
  };

  const handleUploadFiles = async (files: FileList | null) => {
    if (!files || files.length === 0) return;
    try {
      for (const file of Array.from(files)) {
        await createBasicDocument(file.name, 'file', activeFolderTab || undefined);
      }
    } catch (err) {
      console.error(err);
      setError('Impossible de t├®l├®verser les fichiers.');
    }
  };

  const handleUploadFolder = async (files: FileList | null) => {
    if (!files || files.length === 0) return;
    try {
      const folderNames = new Set<string>();
      for (const file of Array.from(files)) {
        const relativePath = (file as File & { webkitRelativePath?: string }).webkitRelativePath;
        if (relativePath) {
          const topFolder = relativePath.split('/')[0];
          if (topFolder) folderNames.add(topFolder);
        }
      }

      for (const folderName of folderNames) {
        await createBasicDocument(folderName, 'folder');
      }

      for (const file of Array.from(files)) {
        const relativePath = (file as File & { webkitRelativePath?: string }).webkitRelativePath;
        const topFolder = relativePath?.split('/')[0] || undefined;
        await createBasicDocument(file.name, 'file', topFolder);
      }
    } catch (err) {
      console.error(err);
      setError('Impossible de t├®l├®verser le dossier.');
    }
  };

  const handleMenuAction = async (action: string) => {
    try {
      if (action === 'upload-files') {
        fileInputRef.current?.click();
        return;
      }

      if (action === 'upload-folder') {
        folderInputRef.current?.click();
        return;
      }

      if (action === 'new-folder') {
        const folderName = window.prompt('Nom du dossier');
        if (!folderName || !folderName.trim()) return;
        await createBasicDocument(folderName.trim(), 'folder');
        return;
      }

      if (action === 'request-file') {
        await createBasicDocument(`Demande de fichier ${new Date().toLocaleDateString('fr-FR')}`, 'request', activeFolderTab || undefined);
        return;
      }

      if (action === 'new-doc') {
        await createBasicDocument('Nouveau document.docx', 'docx', activeFolderTab || undefined);
        return;
      }

      if (action === 'new-text') {
        await createBasicDocument('Nouveau fichier texte.txt', 'txt', activeFolderTab || undefined);
        return;
      }

      if (action === 'new-whiteboard') {
        await createBasicDocument('Nouveau tableau blanc', 'whiteboard', activeFolderTab || undefined);
        return;
      }

      if (action === 'new-sheet') {
        await createBasicDocument('Nouvelle feuille.xlsx', 'xlsx', activeFolderTab || undefined);
        return;
      }

      if (action === 'new-presentation') {
        await createBasicDocument('Nouvelle pr├®sentation.pptx', 'pptx', activeFolderTab || undefined);
        return;
      }

      if (action === 'new-pdf-form') {
        await createBasicDocument('Nouveau formulaire.pdf', 'pdf', activeFolderTab || undefined);
      }
    } catch (err) {
      console.error(err);
      setError('Impossible d\'ex├®cuter cette action.');
    }
  };

  useEffect(() => {
    const listener = (event: Event) => {
      const customEvent = event as CustomEvent<{ action: string }>;
      if (customEvent.detail?.action) {
        void handleMenuAction(customEvent.detail.action);
      }
    };

    window.addEventListener('documents:new-action', listener as EventListener);
    return () => window.removeEventListener('documents:new-action', listener as EventListener);
  }, []);

  useEffect(() => {
    if (folderInputRef.current) {
      folderInputRef.current.setAttribute('webkitdirectory', '');
      folderInputRef.current.setAttribute('directory', '');
    }
  }, []);

  useEffect(() => {
    const handleOutsideClick = (event: globalThis.MouseEvent) => {
      const target = event.target as HTMLElement | null;
      if (target?.closest('[data-row-actions="true"]')) return;
      setOpenActionsId(null);
    };

    document.addEventListener('mousedown', handleOutsideClick);
    return () => document.removeEventListener('mousedown', handleOutsideClick);
  }, []);

  useEffect(() => {
    const handleKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.key === 'Escape') {
        setOpenActionsId(null);
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, []);

  const documentsInCurrentFolder = useMemo(() => {
    if (!activeFolderTab) {
      const foldersAtRoot = documents.filter((doc) => isFolder(doc));
      const filesAtRoot = documents.filter((doc) => !isFolder(doc) && !getParentFolderName(doc));
      return [...foldersAtRoot, ...filesAtRoot];
    }

    const filesInFolder = documents.filter(
      (doc) => !isFolder(doc) && getParentFolderName(doc) === activeFolderTab,
    );
    return filesInFolder;
  }, [documents, activeFolderTab]);

  const displayedDocuments = useMemo(() => {
    if (activeSubTab === 'favorites') {
      return documentsInCurrentFolder.filter((doc) => !isFolder(doc) && isFavoriteDocument(doc.id));
    }

    if (activeSubTab === 'labels') {
      const normalizedSearch = normalizeLabelCode(labelSearchCode);
      const labeledFiles = documentsInCurrentFolder.filter((doc) => !isFolder(doc) && (documentLabelCodes[doc.id] || []).length > 0);
      if (!normalizedSearch) {
        return labeledFiles;
      }
      return labeledFiles.filter((doc) => (documentLabelCodes[doc.id] || []).includes(normalizedSearch));
    }

    return documentsInCurrentFolder;
  }, [
    activeSubTab,
    documentsInCurrentFolder,
    favoriteDocumentIds,
    documentLabelCodes,
    labelSearchCode,
  ]);

  const formatModified = (date: string) => {
    return new Date(date).toLocaleDateString('fr-FR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    });
  };

  const getFileExtension = (doc: DocumentItem): string => {
    const fileName = String(doc.title || '').trim().toLowerCase();
    const index = fileName.lastIndexOf('.');
    if (index >= 0 && index < fileName.length - 1) {
      return fileName.slice(index + 1);
    }

    const mimeType = String((doc as any).mimeType || '').toLowerCase();
    if (mimeType.includes('wordprocessingml')) return 'docx';
    if (mimeType.includes('spreadsheetml')) return 'xlsx';
    if (mimeType.includes('presentationml')) return 'pptx';
    if (mimeType.includes('pdf')) return 'pdf';
    return '';
  };

  const getFileColorClass = (doc: DocumentItem): string => {
    if (isFolder(doc)) return 'text-blue-600';
    const extension = getFileExtension(doc);
    if (extension === 'docx') return 'text-blue-600';
    if (extension === 'xlsx') return 'text-green-600';
    if (extension === 'pptx') return 'text-red-400';
    if (extension === 'pdf') return 'text-orange-500';
    return 'text-gray-500';
  };

  return (
    <div className="space-y-6">
      <input
        ref={fileInputRef}
        type="file"
        className="hidden"
        multiple
        onChange={(e) => {
          void handleUploadFiles(e.target.files);
          e.currentTarget.value = '';
        }}
      />
      <input
        ref={folderInputRef}
        type="file"
        className="hidden"
        multiple
        onChange={(e) => {
          void handleUploadFolder(e.target.files);
          e.currentTarget.value = '';
        }}
      />

      {error && <div className="p-3 mb-4 text-red-700 bg-red-100 rounded">{error}</div>}

      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-3 flex flex-wrap items-center gap-2">
        <button
          onClick={() => setActiveFolderTab(null)}
          className={`px-3 py-1.5 rounded-lg text-xs font-semibold ${activeFolderTab === null ? 'bg-[#2453d6] text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
        >
          Racine
        </button>
        {folderTabs.map((folderName) => (
          <button
            key={folderName}
            onClick={() => setActiveFolderTab(folderName)}
            className={`px-3 py-1.5 rounded-lg text-xs font-semibold ${activeFolderTab === folderName ? 'bg-[#2453d6] text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
          >
            {folderName}
          </button>
        ))}
      </div>

      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-3 flex flex-wrap items-center gap-2">
        <button
          onClick={() => setActiveSubTab('all')}
          className={`px-3 py-1.5 rounded-lg text-xs font-semibold ${activeSubTab === 'all' ? 'bg-[#2453d6] text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
        >
          Tous
        </button>
        <button
          onClick={() => setActiveSubTab('favorites')}
          className={`px-3 py-1.5 rounded-lg text-xs font-semibold ${activeSubTab === 'favorites' ? 'bg-amber-500 text-white' : 'bg-amber-50 text-amber-700 hover:bg-amber-100'}`}
        >
          Favoris ({favoriteDocumentIds.length})
        </button>
        <button
          onClick={() => setActiveSubTab('labels')}
          className={`px-3 py-1.5 rounded-lg text-xs font-semibold ${activeSubTab === 'labels' ? 'bg-emerald-600 text-white' : 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100'}`}
        >
          Etiquettes
        </button>

        {activeSubTab === 'labels' && (
          <input
            type="text"
            value={labelSearchCode}
            onChange={(event) => setLabelSearchCode(event.target.value)}
            placeholder="Code etiquette (ex: ETQ-RH-001)"
