    const syncTheme = (event: StorageEvent) => {
      if (navigatingRef.current) return;
      if (event.key === 'ep_theme_menu_color') {
        setMenuColor(event.newValue || '#173b9f');
      }
      if (event.key === 'ep_theme_login_bg') {
        setLoginBackgroundImage(event.newValue || null);
      }
    };

    const syncThemeCustom = (event: Event) => {
      if (navigatingRef.current) return;
      const detail = (event as CustomEvent<{ menuColor?: string; loginBackgroundImage?: string | null }>).detail;
      if (detail?.menuColor) {
        setMenuColor(detail.menuColor);
      }
      if (Object.prototype.hasOwnProperty.call(detail || {}, 'loginBackgroundImage')) {
        setLoginBackgroundImage(detail?.loginBackgroundImage || null);
      }
    };

    window.addEventListener('storage', syncTheme);
    window.addEventListener('ep_theme_changed', syncThemeCustom as EventListener);
    return () => {
      window.removeEventListener('storage', syncTheme);
      window.removeEventListener('ep_theme_changed', syncThemeCustom as EventListener);
    };
  }, []);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError(null);
    setLoading(true);
    try {
      await login(email.trim().toLowerCase(), password);
      navigatingRef.current = true; // stop any pending theme updates from flashing on this page
      navigate('/documents');
    } catch (err: any) {
      if (err?.response?.status === 401) {
        setError('Email ou mot de passe incorrect.');
      } else if (err?.response?.status) {
        setError(err.response?.data?.message || 'Erreur serveur.');
      } else {
        setError('Impossible de joindre le serveur. V├®rifiez que le backend tourne sur le port 3000.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="relative min-h-screen flex items-center justify-center p-4" style={pageBgStyle}>
      {/* Full-screen background image via <img> ÔÇö far more reliable cross-browser than CSS backgroundImage */}
      {loginBackgroundImage && (
        <img
          src={loginBackgroundImage}
          alt=""
          aria-hidden="true"
          className="fixed inset-0 w-screen h-screen object-cover object-center"
          style={{ zIndex: 0 }}
        />
      )}
      {/* Dark overlay when image is present */}
      {loginBackgroundImage && (
        <div
          className="absolute inset-0"
          style={{ backgroundColor: 'rgba(0,0,0,0.40)', zIndex: 1 }}
        />
      )}
      <div className="relative w-full max-w-md p-8 bg-white/95 shadow-lg rounded-lg backdrop-blur-sm" style={{ zIndex: 2 }}>
        <h2 className="text-2xl font-semibold mb-6" style={{ color: menuColor }}>Connexion</h2>
        {error && <div className="mb-4 p-3 bg-red-100 text-red-700 rounded">{error}</div>}
        <form onSubmit={handleSubmit} autoComplete="on">
          <input
            type="email"
            name="email"
            autoComplete="username"
            className="w-full mb-3 px-3 py-2 border rounded"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <input
            type="password"
            name="password"
            autoComplete="current-password"
            className="w-full mb-3 px-3 py-2 border rounded"
            placeholder="Mot de passe"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button
            type="submit"
            className="w-full py-2 text-white rounded transition"
            style={{ backgroundColor: menuColor }}
            disabled={loading}
          >
            {loading ? 'Connexion...' : 'Se connecter'}
          </button>
        </form>
        <div className="mt-3 text-right">
          <Link to="/forgot-password" className="text-sm hover:underline" style={{ color: menuColor }}>
            Mot de passe oublie ?
          </Link>
        </div>
      </div>
    </div>
  );
}

export default Login;

import { ChangeEvent, FormEvent, useEffect, useMemo, useState } from 'react'
import { Camera, Eye, EyeOff, Mail, Save, ShieldCheck, UserRound } from 'lucide-react'
import { useAuthStore } from '../store/authStore'

const API_ROOT = (import.meta.env.VITE_API_URL || 'http://localhost:3000/api/v1').replace(/\/api(?:\/v\d+)?\/?$/, '')

const toAvatarUrl = (avatar?: string) => {
  if (!avatar) return ''
  if (avatar.startsWith('http://') || avatar.startsWith('https://')) return avatar
  return `${API_ROOT}${avatar.startsWith('/') ? '' : '/'}${avatar}`
}

const splitFullName = (fullName: string) => {
  const parts = fullName.trim().split(/\s+/).filter(Boolean)
  if (parts.length <= 1) {
    return {
      firstName: parts[0] || '',
      lastName: '',
    }
  }

  return {
    firstName: parts.slice(0, -1).join(' '),
    lastName: parts.slice(-1).join(' '),
  }
}

const extractApiError = (err: any, fallback: string) => {
  const message = err?.response?.data?.message
  if (Array.isArray(message)) {
    return message.join(' ')
  }
  if (typeof message === 'string' && message.trim()) {
    return message
  }
  return fallback
}

function Profile() {
  const user = useAuthStore((state) => state.user)
  const syncCurrentUser = useAuthStore((state) => state.syncCurrentUser)
  const saveCurrentUserProfile = useAuthStore((state) => state.saveCurrentUserProfile)
  const uploadAvatar = useAuthStore((state) => state.uploadAvatar)

  const initialName = useMemo(() => splitFullName(user?.fullName || ''), [user?.fullName])

  const [email, setEmail] = useState(user?.email || '')
  const [firstName, setFirstName] = useState(initialName.firstName)
  const [lastName, setLastName] = useState(initialName.lastName)
  const [currentPassword, setCurrentPassword] = useState('')
  const [newPassword, setNewPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [showCurrentPassword, setShowCurrentPassword] = useState(false)
  const [showNewPassword, setShowNewPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState<string | null>(null)
  const [isSaving, setIsSaving] = useState(false)
  const [isUploadingAvatar, setIsUploadingAvatar] = useState(false)
  const [avatarUploadPopup, setAvatarUploadPopup] = useState<{ type: 'success' | 'error'; message: string } | null>(null)

  useEffect(() => {
    syncCurrentUser().catch(() => undefined)
  }, [syncCurrentUser])

  useEffect(() => {
    const name = splitFullName(user?.fullName || '')
    setEmail(user?.email || '')
    setFirstName(name.firstName)
    setLastName(name.lastName)
  }, [user?.email, user?.fullName])

  useEffect(() => {
    if (!avatarUploadPopup) return
    const timeout = window.setTimeout(() => setAvatarUploadPopup(null), 2500)
    return () => window.clearTimeout(timeout)
  }, [avatarUploadPopup])

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault()
    setError(null)
    setSuccess(null)

    const normalizedEmail = email.trim().toLowerCase()
    const normalizedFirstName = firstName.trim()
    const normalizedLastName = lastName.trim()
    const fullName = `${normalizedFirstName} ${normalizedLastName}`.trim()

    if (!normalizedEmail) {
      setError("L'adresse e-mail est obligatoire.")
      return
    }

    if (!normalizedFirstName && !normalizedLastName) {
      setError('Le nom complet est obligatoire.')
      return
    }

    if (newPassword) {
      if (!currentPassword) {
        setError('Le mot de passe actuel est obligatoire pour d├®finir un nouveau mot de passe.')
        return
      }

      if (newPassword.length < 8) {
        setError('Le nouveau mot de passe doit contenir au moins 8 caract├¿res.')
        return
      }

      if (newPassword !== confirmPassword) {
        setError('La confirmation du nouveau mot de passe ne correspond pas.')
        return
      }
    }

    setIsSaving(true)
    try {
      await saveCurrentUserProfile({
        email: normalizedEmail,
        fullName,
        currentPassword: currentPassword || undefined,
        password: newPassword || undefined,
      })
      await syncCurrentUser()

      setCurrentPassword('')
      setNewPassword('')
      setConfirmPassword('')
      setSuccess('Vos informations personnelles ont ├®t├® mises ├á jour.')
    } catch (err: any) {
      setError(extractApiError(err, 'La mise ├á jour du profil a ├®chou├®.'))
    } finally {
      setIsSaving(false)
    }
  }

  const handleAvatarChange = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (!file) return

    if (!file.type.startsWith('image/')) {
      setError('Veuillez s├®lectionner une image valide (PNG, JPG, JPEG, WEBP).')
      return
    }

    if (file.size > 5 * 1024 * 1024) {
      setError('La taille maximale autoris├®e est de 5 Mo.')
      return
    }

    setError(null)
    setSuccess(null)
    setAvatarUploadPopup(null)
    setIsUploadingAvatar(true)
    try {
      await uploadAvatar(file)
      await syncCurrentUser()
      setSuccess('Photo de profil mise ├á jour avec succ├¿s.')
      setAvatarUploadPopup({ type: 'success', message: 'Upload r├®ussi: photo de profil mise ├á jour.' })
    } catch (err: any) {
      const message = extractApiError(err, "Impossible d'uploader la photo de profil.")
      setError(message)
      setAvatarUploadPopup({ type: 'error', message })
    } finally {
      setIsUploadingAvatar(false)
      event.target.value = ''
    }
  }

  return (
    <div className="space-y-6">
      {avatarUploadPopup && (
        <div className="fixed right-5 top-5 z-50">
          <div
            className={`rounded-xl border px-4 py-3 text-sm font-medium shadow-lg ${
