                    </p>
                  )}
                  {selectedRequiredDocument && (
                    <p className="mt-1 text-xs text-gray-600">Pi├¿ce s├®lectionn├®e: {selectedRequiredDocument}</p>
                  )}
                  {attachments.length > 0 && (
