import React, { useMemo, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useAuthStore } from '../store/authStore';
import { registerInvited } from '../services/auth';

function Register() {
  const [email, setEmail] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [searchParams] = useSearchParams();
  const inviteMode = searchParams.get('invite') === '1';
  const [fullName, setFullName] = useState(() => {
    const prenoms = searchParams.get('prenoms') || '';
    const nom = searchParams.get('nom') || '';
    return `${prenoms} ${nom}`.trim();
  });
  const invitedRole = useMemo(() => searchParams.get('role') || 'user', [searchParams]);
  const invitedEmail = useMemo(() => searchParams.get('email') || '', [searchParams]);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const register = useAuthStore((state) => state.register);
  const navigate = useNavigate();

  React.useEffect(() => {
    if (invitedEmail) {
      setEmail(invitedEmail);
    }
  }, [invitedEmail]);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError(null);
    setSuccess(null);
    setLoading(true);
    try {
      if (inviteMode) {
        await registerInvited({
          email,
          username,
          password,
          fullName,
          role: invitedRole,
        });
        setSuccess('Votre formulaire a ├®t├® envoy├®. Votre compte reste d├®sactiv├® jusquÔÇÖ├á activation par lÔÇÖadministrateur.');
        window.setTimeout(() => navigate('/login'), 2500);
      } else {
        await register(email, username, password, fullName);
        navigate('/documents');
      }
    } catch (err: any) {
      setError(err.response?.data?.message || 'Impossible de cr├®er un compte.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-md mx-auto mt-20 p-8 bg-white shadow-lg rounded-lg">
      <h2 className="text-2xl font-semibold mb-6">{inviteMode ? 'Formulaire invit├®' : 'Inscription'}</h2>
      {inviteMode && (
        <div className="mb-4 p-3 bg-blue-100 text-blue-700 rounded text-sm">
          Vous avez ├®t├® invit├®. Votre compte sera cr├®├® en statut d├®sactiv├® et devra ├¬tre activ├® par lÔÇÖadministrateur.
        </div>
      )}
      {error && <div className="mb-4 p-3 bg-red-100 text-red-700 rounded">{error}</div>}
      {success && <div className="mb-4 p-3 bg-green-100 text-green-700 rounded">{success}</div>}
      <form onSubmit={handleSubmit}>
        <input
          type="email"
          className="w-full mb-3 px-3 py-2 border rounded"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          readOnly={Boolean(invitedEmail)}
          required
        />
        <input
          type="text"
          className="w-full mb-3 px-3 py-2 border rounded"
          placeholder="Nom d'utilisateur"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          required
        />
        <input
          type="text"
          className="w-full mb-3 px-3 py-2 border rounded"
          placeholder="Nom complet"
          value={fullName}
          onChange={(e) => setFullName(e.target.value)}
          required
        />
        <input
          type="password"
          className="w-full mb-3 px-3 py-2 border rounded"
          placeholder="Mot de passe"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <button
          type="submit"
          className="w-full py-2 bg-green-600 text-white rounded hover:bg-green-700 transition"
          disabled={loading}
        >
          {loading ? 'Envoi...' : inviteMode ? 'Envoyer le formulaire' : "S'inscrire"}
        </button>
      </form>
      {!inviteMode && (
        <p className="mt-4 text-sm text-gray-500">
          D├®j├á membre ? <a href="/login" className="text-blue-600">Se connecter</a>
        </p>
      )}
    </div>
  );
}

export default Register;

import React, { useMemo, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { resetPassword } from '../services/auth';

function ResetPassword() {
  const [searchParams] = useSearchParams();
  const token = useMemo(() => searchParams.get('token') || '', [searchParams]);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError(null);
    setMessage(null);

    if (!token) {
      setError('Lien invalide. Le token de reinitialisation est absent.');
      return;
    }

    if (newPassword.length < 8) {
      setError('Le mot de passe doit contenir au moins 8 caracteres.');
      return;
    }

    if (newPassword !== confirmPassword) {
      setError('Les mots de passe ne correspondent pas.');
      return;
    }

    setLoading(true);
    try {
      const result = await resetPassword({ token, newPassword });
      setMessage(result.message || 'Mot de passe reinitialise avec succes.');
      setNewPassword('');
      setConfirmPassword('');
    } catch (err: any) {
      setError(err?.response?.data?.message || 'Impossible de reinitialiser le mot de passe.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-md mx-auto mt-20 p-8 bg-white shadow-lg rounded-lg">
      <h2 className="text-2xl font-semibold mb-6">Reinitialiser le mot de passe</h2>

      {message && <div className="mb-4 p-3 bg-green-100 text-green-700 rounded">{message}</div>}
      {error && <div className="mb-4 p-3 bg-red-100 text-red-700 rounded">{error}</div>}

      <form onSubmit={handleSubmit} autoComplete="off">
        <input
          type="password"
          className="w-full mb-3 px-3 py-2 border rounded"
          placeholder="Nouveau mot de passe"
          value={newPassword}
          onChange={(e) => setNewPassword(e.target.value)}
          required
          minLength={8}
        />
        <input
          type="password"
          className="w-full mb-3 px-3 py-2 border rounded"
          placeholder="Confirmer le nouveau mot de passe"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
          required
          minLength={8}
        />

        <button
          type="submit"
          className="w-full py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition"
          disabled={loading}
        >
          {loading ? 'Validation...' : 'Valider'}
        </button>
      </form>

      <p className="mt-4 text-sm text-gray-500">
        Retour a la <Link to="/login" className="text-blue-600">connexion</Link>
      </p>
    </div>
  );
}

export default ResetPassword;

