      setGeneratedFileName(generated.fileName)
      const generatedFile = new File([generated.generatedContent], generated.fileName, { type: 'text/plain;charset=utf-8' })
      await uploadDocumentFile(generatedFile, {
        generatedFromSharedTemplate: true,
        subEntityCode: user?.subEntityCode || undefined,
        title: generated.fileName.replace(/\.[^.]+$/, ''),
      })

      setFeedback({ type: 'success', message: `Document g├®n├®r├®: ${generated.fileName}` })
    } catch (err: any) {
      setFeedback({ type: 'error', message: err?.response?.data?.message || 'Impossible de g├®n├®rer le document.' })
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div className="space-y-5">
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">
        <h2 className="text-lg font-semibold text-gray-800">Templates partag├®s</h2>
        <p className="text-xs text-gray-500 mt-1">Les templates mis ├á votre disposition par l'administrateur.</p>
      </div>

      {loading && <div className="bg-blue-50 border border-blue-100 text-blue-700 rounded-xl p-3 text-xs">Chargement...</div>}
      {error && <div className="bg-red-50 border border-red-200 text-red-700 rounded-xl p-3 text-xs">{error}</div>}

      {!loading && !error && (
        <div className="space-y-5">
          <section className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5 space-y-3">
            <h3 className="text-sm font-semibold text-gray-800">Liste des templates partag├®s</h3>
            {sharedTemplates.length === 0 ? (
              <div className="text-xs text-gray-500 bg-gray-50 border border-gray-100 rounded-lg p-3">
                Aucun template partag├® pour votre compte.
              </div>
            ) : (
              <div className="space-y-3">
                {sharedTemplates.map((item) => (
                  <div
                    key={item.id}
                    className={`border rounded-xl p-4 transition ${
                      selectedTemplateId === item.id ? 'border-[#2453d6] bg-blue-50' : 'border-gray-200 bg-gray-50'
                    }`}
                  >
                    <p className="text-sm font-semibold text-gray-800">{item.name}</p>
                    <p className="text-xs text-gray-500 mt-1">{item.fileName} ┬À {item.fileType.toUpperCase()}</p>
                    <div className="mt-3 flex flex-wrap gap-2">
                      <button
                        type="button"
                        onClick={() => {
                          setSelectedTemplateId(item.id)
                          setFeedback(null)
                        }}
                        className="px-3 py-1.5 rounded-lg bg-green-100 text-green-700 text-xs font-semibold hover:bg-green-200"
                      >
                        Formulaire
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </section>

          <section className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5 space-y-4">
            <h3 className="text-sm font-semibold text-gray-800">Formulaire</h3>
            <p className="text-xs text-gray-600">Template s├®lectionn├®: <span className="font-semibold">{selectedTemplate?.name || 'Aucun'}</span></p>

            {feedback && (
              <div className={`rounded-lg px-3 py-2 text-xs ${feedback.type === 'success' ? 'bg-green-50 border border-green-200 text-green-700' : 'bg-red-50 border border-red-200 text-red-700'}`}>
                {feedback.message}
              </div>
            )}

            <form onSubmit={handleGenerate} className="space-y-3">
              {generationFields.length === 0 && (
                <p className="text-xs text-gray-500">Aucune variable d├®tect├®e pour ce template.</p>
              )}

              {generationFields.map((field) => (
                <div key={field.key} className="space-y-1">
                  <label className="text-xs font-medium text-gray-700">{field.label} ({field.key})</label>
                  {field.fieldType === 'textarea' ? (
                    <textarea
                      value={generationValues[field.key] || ''}
                      onChange={(e) => setGenerationValues((prev) => ({ ...prev, [field.key]: e.target.value }))}
                      className="w-full border rounded-lg px-3 py-2 text-xs min-h-[90px]"
                      placeholder={field.placeholder || ''}
                      required={Boolean(field.required)}
                    />
                  ) : (
                    <input
                      type={field.fieldType === 'number' ? 'number' : field.fieldType === 'date' ? 'date' : 'text'}
                      value={generationValues[field.key] || ''}
                      onChange={(e) => setGenerationValues((prev) => ({ ...prev, [field.key]: e.target.value }))}
                      className="w-full border rounded-lg px-3 py-2 text-xs"
                      placeholder={field.placeholder || ''}
                      required={Boolean(field.required)}
                    />
                  )}
                </div>
              ))}

              <button
                type="submit"
                disabled={!selectedTemplateId || submitting}
                className="bg-[#2453d6] text-white rounded-lg px-3 py-2 text-xs font-semibold disabled:opacity-40"
              >
                {submitting ? 'G├®n├®ration...' : 'G├®n├®rer et enregistrer le document'}
              </button>
            </form>

            {generatedContent && (
              <div className="border border-gray-200 rounded-lg p-3 bg-gray-50">
                <p className="text-xs font-semibold text-gray-700">Aper├ºu g├®n├®r├® ({generatedFileName || 'document'})</p>
                <pre className="mt-2 text-[11px] text-gray-700 whitespace-pre-wrap max-h-56 overflow-auto">{generatedContent}</pre>
              </div>
            )}
          </section>
        </div>
      )}
    </div>
  )
}

export default SharedTemplates

import React, { useEffect, useRef, useState } from 'react'
import { PenLine, Send, ShieldCheck, CheckCircle2, XCircle, Upload, FileUp, Workflow, PenSquare, MapPin, PlusCircle, Trash2, PlayCircle, PenTool, FileText, Eye } from 'lucide-react'
import { fetchDocumentById, fetchDocuments, uploadDocumentFile } from '../services/documents'
import { fetchAppSetting, fetchSignatureProviderConfig } from '../services/administration'
import { fetchWorkflows, fetchWorkflowDetails, advanceWorkflow, fetchWorkflowTemplates, createWorkflow, executeWorkflow } from '../services/workflows'
import { fetchSignataires, AppUserRecord } from '../services/users'
import {
  fetchSignatures,
  requestSignature,
  signDocument,
  getPendingSignatures,
  respondToSignatureRequest,
