import { WorkflowExecution, WorkflowItem, WorkflowTemplateItem } from '../types/workflow'

type SignatureWorkflowRow = {
  executionId: string
  workflowId: string
  workflowName: string
  documentId: string
  documentTitle: string
  status: string
  currentStep: number
  actionType: 'signature' | 'validation'
  isMyTurn: boolean
}

type PendingSelfDoc = {
  doc: DocumentItem
  uploadedAt: string
}

type SignedSelfDoc = {
  doc: DocumentItem
  signedAt: string
}

function Signatures() {
  const user = useAuthStore((state) => state.user)
  const [documents, setDocuments] = useState<DocumentItem[]>([])
  const [selectedDocumentId, setSelectedDocumentId] = useState('')
  const [signatures, setSignatures] = useState<SignatureItem[]>([])
  const [pendingRequests, setPendingRequests] = useState<SignatureRequest[]>([])
  const [requestTo, setRequestTo] = useState('')
  const [requestMessage, setRequestMessage] = useState('')
  const [signatureHash, setSignatureHash] = useState('')
  const [workflowsRows, setWorkflowsRows] = useState<SignatureWorkflowRow[]>([])
  const localFiles = useSignatureFilesStore((s) => s.localFiles)
  const setLocalFiles = useSignatureFilesStore((s) => s.setLocalFiles)
  const selectedLocalKeys = useSignatureFilesStore((s) => s.selectedLocalKeys)
  const setSelectedLocalKeys = useSignatureFilesStore((s) => s.setSelectedLocalKeys)
  const [uploadingLoading, setUploadingLoading] = useState(false)
  const [pendingSelfDocs, setPendingSelfDocs] = useState<PendingSelfDoc[]>([])
  const [selectedPendingIds, setSelectedPendingIds] = useState<string[]>([])
  const [signingLoading, setSigningLoading] = useState(false)
