                                      </div>
                                      <div className="flex items-center gap-2">
                                        {isSaved
                                          ? <span className="px-3 py-1.5 rounded-lg bg-green-100 text-green-700 text-xs font-semibold cursor-pointer" onClick={() => { void openPositioningForDocument(documentId) }}>Ô£ô Positionn├® ({zoneCount})</span>
                                          : <button
                                            type="button"
                                            onClick={() => { void openPositioningForDocument(documentId) }}
                                            className="px-3 py-1.5 rounded-lg bg-violet-600 hover:bg-violet-700 text-white text-xs font-semibold"
                                          >
                                            Positionner
                                          </button>}
                                        <button
                                          type="button"
                                          onClick={() => setWfForm(prev => ({
                                            ...prev,
                                            docsToSign: prev.docsToSign.filter((id) => id !== documentId),
