                        <div className="space-y-3">
                          <button type="button" onClick={() => wfDocsToSignRef.current?.click()} className="w-full flex items-center justify-center gap-2 border-2 border-dashed border-red-300 rounded-lg px-3 py-3 text-sm text-red-600 hover:bg-red-50 transition-colors font-medium cursor-pointer"><Upload size={16} />S├®lect. fichiers</button>
                          {wfForm.docsToSignUploaded.length > 0 && (
                            <div className="space-y-2">
                              {wfForm.docsToSignUploaded.map((file, idx) => {
                                const fk = getFileKey(file)
                                const zc = wfZonesByFileKey[fk]?.length || 0
                                return (
                                  <div key={fk} className="flex items-center justify-between gap-2 rounded-lg border border-gray-200 bg-white px-3 py-2">
                                    <div className="min-w-0"><p className="truncate text-sm font-medium text-gray-800">{file.name}</p><p className="text-xs text-gray-500">{(file.size / 1024).toFixed(2)} KB ┬À {zc} zone(s)</p></div>
                                    <div className="flex items-center gap-2">
                                      {zc > 0
                                        ? <span className="px-3 py-1.5 rounded-lg bg-green-100 text-green-700 text-xs font-semibold cursor-pointer" onClick={() => openWfPositioning(file)}>Ô£ô Positionn├® ({zc})</span>
                                        : <button type="button" onClick={() => openWfPositioning(file)} className="px-3 py-1.5 rounded-lg bg-violet-600 hover:bg-violet-700 text-white text-xs font-semibold">Positionner</button>}
