                      <div className="text-xs text-gray-500">{wfForm.docsToSign.length + wfForm.docsToSignUploaded.length > 0 ? `${wfForm.docsToSign.length + wfForm.docsToSignUploaded.length} fichier(s) s├®lectionn├®(s)` : 'Aucun fichier choisi'}</div>
