                          <textarea rows={2} value={wfForm.notifyEmails} onChange={(e) => setWfForm(prev => ({ ...prev, notifyEmails: e.target.value }))} placeholder="S├®parer les emails par des virgules" className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm text-gray-700 focus:outline-none focus:ring-2 focus:ring-amber-400 bg-white" />
