                      <div><p className="font-semibold text-gray-800">Description</p><p>{wfForm.description || 'ÔÇö'}</p></div>
                      <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 space-y-3">
                        <div>
                          <p className="font-semibold text-gray-800 flex items-center gap-2"><CheckCircle2 size={18} className="text-green-600" /> ├ëtapes de validation ({wfForm.validationSteps.filter(s => s.approverId).length})</p>
                          <ul className="list-disc list-inside text-gray-600 ml-6">{wfForm.validationSteps.filter(s => s.approverId).map((s, i) => <li key={s.id}>Validateur {i + 1}: {wfSignataires.find(u => u.id === s.approverId)?.fullName || s.approverId}</li>)}</ul>
                        </div>
                        <div>
                          <p className="font-semibold text-gray-800 flex items-center gap-2"><PenTool size={18} className="text-blue-600" /> ├ëtapes de signature ({wfForm.signatureSteps.filter(s => s.signerId).length})</p>
                          <ul className="list-disc list-inside text-gray-600 ml-6">{wfForm.signatureSteps.filter(s => s.signerId).map((s, i) => <li key={s.id}>Signataire {i + 1}: {wfSignataires.find(u => u.id === s.signerId)?.fullName || s.signerId}</li>)}</ul>
                        </div>
                      </div>
                    </div>
                    {wfError && <div className="p-3 bg-red-100 text-red-800 rounded-lg text-sm font-medium">{wfError}</div>}
                    <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                      <p className="text-sm font-semibold text-gray-800 mb-4">Actions disponibles</p>
                      <div className="flex flex-wrap gap-3">
                        <button type="submit" disabled={wfSubmitting} className="px-6 py-2.5 bg-green-600 hover:bg-green-700 disabled:opacity-60 disabled:cursor-wait text-white text-sm font-semibold rounded-lg transition flex items-center gap-2">{wfSubmitting ? <><span className="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full" /> D├®marrageÔÇª</> : <><PlayCircle size={18} /> D├®marrer</>}</button>
                      </div>
