                  {wfStep < WF_MAX_STEP ? (
                    <button type="button" onClick={wfNextStep} className="px-4 py-2 rounded-lg bg-[#2453d6] hover:bg-[#1f47bb] text-white text-sm font-semibold">Suivant</button>
                  ) : null}
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* ÔöÇÔöÇ Workflow Positioning Modal ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      {wfPositioningFile && wfPositioningFileUrl && (
        <div className="fixed inset-0 bg-black/40 z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-lg border border-gray-200 w-full max-w-6xl h-[88vh] overflow-hidden flex flex-col">
            <div className="px-4 py-3 border-b border-gray-200 flex items-center justify-between shrink-0">
              <div>
                <p className="text-lg font-semibold text-gray-800 flex items-center gap-2">
                  <MapPin size={18} className="text-violet-600" />
                  Zones de signature ÔÇö {wfPositioningFile.name}
                </p>
                <p className="text-sm text-gray-500">{wfCurrentZones.length} zone(s) ┬À Cliquez pour ajouter, glissez pour d├®placer, coin Ôåÿ pour redimensionner</p>
              </div>
              <div className="flex items-center gap-2">
