                    {/* Resize handle bottom-right */}
                    <div
                      className="absolute bottom-0 right-0 w-4 h-4 cursor-nwse-resize bg-blue-600 hover:bg-blue-800 rounded-tl-sm opacity-60 hover:opacity-100 transition-opacity"
